if (!p.ok) return [{ json: { ok: false, status: p.status, body: p.body, reason: p.reason } }];
return [{ json: { ok: true, lead_id: c.lead_id, answers: p.answers, request_id: p.request_id, confirm_adviser: p.confirm_adviser, key: L.answersKey(c.lead_id, p.request_id, !!p.confirm_adviser) } }];

