const L = require('lv-automation').w39;
const r = $input.first().json;
const q = $('Resolve caller + parse (answers)').first().json;
const plan = L.decideAnswers({ lead: r.lead, answers: q.answers, request_id: q.request_id, confirm_adviser: q.confirm_adviser || null, prior: r.prior || null, now: Date.now(), oobAgeBooks: L.OUT_OF_BAND_AGE_BOOKS });
return [{ json: { lead_id: q.lead_id, plan } }];

const L = require('lv-automation').w39;
const p = $json.plan;
return [{ json: { status: p.status || 401, body: p.body || { error: 'try_again' }, reason: p.reason || null } }];

const L = require('lv-automation').w39;
const r = $input.first().json;
const d = $('Decide (w39.decideAnswers)').first().json;
// pool: a test lead is shown (and routed to) only a test practice, a real lead never one (lib/routing-split.mjs)
return [{ json: { lead_id: d.lead_id, step: L.coverStep({ plan: d.plan, lead: r.lead || { id: d.lead_id }, brokers: r.brokers || [], pool: L.routingPool(r.lead, $env) }) } }];

const L = require('lv-automation').w39;
const s = $('Adviser step (w39.coverStep)').first().json.step;
return [{ json: s.route || s.hold }];

const L = require('lv-automation').w39;
const d = $('Decide (w39.decideAnswers)').first().json;
let claimed = false;
try { claimed = Number($('Save answers + timeline + cancel stall (one statement)').first().json.claimed) > 0; } catch (e) { claimed = false; } // replay: Save did not run
let step = null;
try { step = $('Adviser step (w39.coverStep)').first().json.step; } catch (e) { step = null; } // not a cover path
return [{ json: L.answer({ plan: d.plan, step, broker_id: $input.first().json.broker_id || null, claimed }) }];

const L = require('lv-automation').w39;
// decided shape (smc-whatsapp-send writes the communications row; correlation w39:<path>:<lead> = once per lead)
return $input.all().map((i) => ({ json: i.json.message }));

const L = require('lv-automation').w39;
const j = $input.first().json;
const c = L.resolveCaller(j.headers || {}, $env, Date.now());
if (!c.ok) return [{ json: { ok: false, status: c.status, body: c.body, reason: c.reason } }];
const p = L.parseAdviser(j.body);
if (!p.ok) return [{ json: { ok: false, status: p.status, body: p.body, reason: p.reason } }];
return [{ json: { ok: true, lead_id: c.lead_id, request_id: p.request_id, confirm_adviser: p.confirm_adviser, key: L.adviserKey(c.lead_id, p.request_id, !!p.confirm_adviser) } }];

